is_even() { [ $(( $1 % 2 )) -eq 0 ]; }
is_even 4 && echo even

fail() {
  printf 'error: %s\n' "$1" >&2
  return 1
}

print_all() {
  local a
  for a in "$@"; do
    printf '%s\n' "$a"
  done
}

require_one() {
  if [ "$#" -ne 1 ]; then
    printf 'expected 1 argument, got %d\n' "$#" >&2
    return 2
  fi
}

while [ "$#" -gt 0 ]; do
  case "$1" in
    -v) verbose=1; shift;;
    -o) out=$2; shift 2;;
    --) shift; break;;
    *) echo "unknown: $1" >&2; exit 1;;
  esac
done

function greet {
  echo "Hello $1"
}
greet World

while getopts 'ab:' opt; do
  case "$opt" in
    a) flag_a=1;;
    b) bval=$OPTARG;;
    *) exit 1;;
  esac
done
shift $((OPTIND - 1))

run() {
  local quiet=0
  while [ "$#" -gt 0 ]; do
    case "$1" in
      -q) quiet=1; shift;;
      *) break;;
    esac
  done
  [ "$quiet" -eq 1 ] || echo "running: $*"
  "$@"
}

main() {
  echo "args: $*"
}
if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  main "$@"
fi
